android.extraProguardRules:
# Razorpay checkout (kept for when online payment is switched on)
-keepclassmembers class * { @android.webkit.JavascriptInterface <methods>; }
-keepattributes JavascriptInterface
-keepattributes *Annotation*
-dontwarn com.razorpay.**
-keep class com.razorpay.** {*;}
-optimizations !method/inlining/*
-keepclasseswithmembers class * { public void onPayment*(...); }
# Release builds print no debug, verbose or info lines: the SMS reader library logs each message it
# receives, and a sign-in code must not be left in the phone's log.
-assumenosideeffects class android.util.Log {
 public static int v(...);
 public static int d(...);
 public static int i(...);
}
